local encoded=table.concat(chunks)
local ok,source=pcall(function()
    return (encoded:gsub("..",function(pair)
        local n=tonumber(pair,16)
        if not n then error("Invalid file data") end
        return string.char(n)
    end))
end)
if not ok then warn("ZYROX: "..tostring(source));return end
if #source ~= 375863 then warn("ZYROX: File data incomplete");return end
if type(loadstring) ~= "function" then warn("ZYROX: loadstring unavailable");return end
local compiled,fn,message=pcall(loadstring,source,"ZyroxProtected")
if not compiled then warn("ZYROX: "..tostring(fn));return end
if type(fn)~="function" then warn("ZYROX: "..tostring(message));return end
local ran,err=pcall(fn)
if not ran then warn("ZYROX: "..tostring(err)) end
